1	import { useState, useCallback } from 'react';
2	import { supabase } from '@/integrations/supabase/client';
3	import { BankTransaction } from '@/types/banking';
4	import { toast } from 'sonner';
5	import { wideDebug, wideInfo, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';
6	import { handleError } from '@/shared/lib/error-handler';
7	
8	export interface ReconciliationMatch {
9	  bankTxnId: number;
10	  bankTxn: BankTransaction;
11	  contaId: string;
12	  contaDescricao: string;
13	  contaValor: number;
14	  contaVencimento: string | null;
15	  contaStatus: string;
16	  contaTipo: string;
17	  contaOrigem: string;
18	  confidence: number; // 0-100
19	  matchReason: string;
20	  pass?: string; // 'algorithmic' | 'ai_batch' | 'ai_detailed'
21	}
22	
23	export interface ReconciliationStats {
24	  total: number;
25	  pass1: number;
26	  pass2: number;
27	  pass3: number;
28	  total_matches: number;
29	  unmatched: number;
30	}
31	
32	export interface CreditCardReconciliationMatch {
33	  csvTxnId: number;
34	  csvDescricao: string;
35	  csvValor: number;
36	  csvData: string;
37	  nfTxnId: number;
38	  nfDescricao: string;
39	  nfValor: number;
40	  nfData: string;
41	  confidence: number;
42	}
43	
44	export interface ContaCandidate {
45	  id: string;
46	  descricao: string;
47	  valor: number;
48	  data_vencimento: string | null;
49	  data_competencia: string | null;
50	  status: string;
51	  tipo: string;
52	  origem: string;
53	  forma_pagamento: string | null;
54	}
55	
56	export interface UnmatchedBankTxn {
57	  bankTxn: BankTransaction;
58	}
59	
60	// ── Helpers ──
61	
62	// Bank internal charges — these rarely correspond to a conta a pagar/receber
63	const BANK_FEE_PATTERN = /\b(tarifa|tar\.|taxa\b|iof|anuidade|manutencao|cesta\s*de\s*servico|encargo|agrupada)/i;
64	
65	function isBankFee(desc: string): boolean {
66	  return BANK_FEE_PATTERN.test(desc);
67	}
68	
69	// Text normalization for description comparison
70	const BANKING_NOISE = /\b(pix|ted|doc|deb|cred|auto|pag|pagamento|recebido|enviado|transf|transferencia|compra|parcela|parc|ref|nsu|aut|pgto|tar|tarifa|ocorrencia|agrupadas?)\b/gi;
71	const PUNCTUATION = /[*\-/\\.,;:()#[\]{}|'"!?&@=+<>_~^`]/g;
72	const DATE_PATTERN = /\d{2}\/\d{2}\/\d{4}/g;
73	const MULTI_SPACES = /\s{2,}/g;
74	const CNPJ_PATTERN = /(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/g;
75	const CPF_PATTERN = /(\d{3}\.?\d{3}\.?\d{3}-?\d{2})/g;
76	
77	function normalizeDesc(desc: string): string {
78	  return desc
79	    .toLowerCase()
80	    .replace(DATE_PATTERN, ' ')
81	    .replace(PUNCTUATION, ' ')
82	    .replace(BANKING_NOISE, ' ')
83	    .replace(MULTI_SPACES, ' ')
84	    .trim();
85	}
86	
87	function extractDocNumbers(desc: string): string[] {
88	  const cnpjs = desc.match(CNPJ_PATTERN) || [];
89	  const cpfs = desc.match(CPF_PATTERN) || [];
90	  return [...cnpjs, ...cpfs].map(d => d.replace(/[.\-/]/g, ''));
91	}
92	
93	function extractMeaningfulWords(normalized: string): string[] {
94	  return normalized.split(/\s+/).filter(w => w.length > 3);
95	}
96	
97	function calcDescriptionScore(bankDesc: string, contaDesc: string): { score: number; reason: string; hasMatch: boolean } {
98	  // 1) CNPJ/CPF match — strongest signal
99	  const bankDocs = extractDocNumbers(bankDesc);
100	  const contaDocs = extractDocNumbers(contaDesc);
101	  if (bankDocs.length > 0 && contaDocs.length > 0) {
102	    const docMatch = bankDocs.some(bd => contaDocs.includes(bd));
103	    if (docMatch) return { score: 20, reason: 'CNPJ/CPF identico', hasMatch: true };
104	  }
105	
106	  const bankNorm = normalizeDesc(bankDesc);
107	  const contaNorm = normalizeDesc(contaDesc);
108	
109	  // 2) One description contains the other
110	  if (bankNorm.length > 6 && contaNorm.length > 6) {
111	    if (bankNorm.includes(contaNorm) || contaNorm.includes(bankNorm)) {
112	      return { score: 18, reason: 'Descricao contida', hasMatch: true };
113	    }
114	  }
115	
116	  // 3) Word overlap
117	  const bankWords = extractMeaningfulWords(bankNorm);
118	  const contaWords = extractMeaningfulWords(contaNorm);
119	
120	  if (bankWords.length === 0 || contaWords.length === 0) {
121	    return { score: 0, reason: '', hasMatch: false };
122	  }
123	
124	  const matchedWords: string[] = [];
125	  for (const cw of contaWords) {
126	    if (bankWords.some(bw => bw.includes(cw) || cw.includes(bw))) {
127	      matchedWords.push(cw);
128	    }
129	  }
130	
131	  if (matchedWords.length === 0) return { score: 0, reason: '', hasMatch: false };
132	
133	  const ratio = matchedWords.length / contaWords.length;
134	  let score: number;
135	  if (ratio >= 0.5 && matchedWords.length >= 2) score = 15;
136	  else if (matchedWords.length >= 3) score = 12;
137	  else if (matchedWords.length >= 2) score = 8;
138	  else score = 5;
139	
140	  return { score, reason: `Palavras: ${matchedWords.slice(0, 3).join(', ')}`, hasMatch: true };
141	}
142	
143	function calcPaymentMethodScore(bankDesc: string, contaFormaPgto: string | null): number {
144	  if (!contaFormaPgto) return 0;
145	  const desc = bankDesc.toLowerCase();
146	  if (contaFormaPgto === 'pix' && /pix/i.test(desc)) return 5;
147	  if (contaFormaPgto === 'boleto' && /boleto|titulo|cobranca/i.test(desc)) return 5;
148	  if (contaFormaPgto === 'transferencia' && /ted|doc|transf/i.test(desc)) return 5;
149	  if (contaFormaPgto === 'debito_automatico' && /deb.*auto/i.test(desc)) return 5;
150	  return 0;
151	}
152	
153	function dateDiffDays(d1: Date, d2: Date): number {
154	  return Math.abs((d1.getTime() - d2.getTime()) / (1000 * 60 * 60 * 24));
155	}
156	
157	// ── Main hook ──
158	
159	export function useReconciliation() {
160	  const [bankMatches, setBankMatches] = useState<ReconciliationMatch[]>([]);
161	  const [unmatchedTxns, setUnmatchedTxns] = useState<UnmatchedBankTxn[]>([]);
162	  const [cardMatches, setCardMatches] = useState<CreditCardReconciliationMatch[]>([]);
163	  const [loading, setLoading] = useState(false);
164	  const [reconciliationStats, setReconciliationStats] = useState<ReconciliationStats | null>(null);
165	
166	  const findBankMatches = useCallback(async (
167	    accountId: number,
168	  ) => {
169	    setLoading(true);
170	    try {
171	      // 1) Resolve loja_id from the bank account itself
172	      const { data: accountData, error: accErr } = await supabase
173	        .from('bank_accounts')
174	        .select('loja_id')
175	        .eq('id', accountId)
176	        .single();
177	
178	      if (accErr) throw accErr;
179	      const accountLojaId = accountData?.loja_id;
180	
181	      // 2) Get unreconciled bank transactions
182	      const { data: bankTxns, error: bankErr } = await supabase
183	        .from('bank_transactions')
184	        .select('*')
185	        .eq('bank_account_id', accountId)
186	        .eq('conciliado', false)
187	        .order('data', { ascending: false });
188	
189	      if (bankErr) throw bankErr;
190	      if (!bankTxns || bankTxns.length === 0) {
191	        setBankMatches([]);
192	        setUnmatchedTxns([]);
193	        setLoading(false);
194	        return;
195	      }
196	
197	      // 3) Get candidate contas ONLY from the same store
198	      const contasQuery = supabase
199	        .from('contas_pagar_receber')
200	        .select('id, descricao, valor, data_vencimento, data_pagamento, status, tipo, origem, forma_pagamento, data_competencia')
201	        .eq('loja_id', accountLojaId)
202	        .in('status', ['pendente', 'pago', 'recebido'])
203	        .or('forma_pagamento.is.null,forma_pagamento.neq.cartao_credito')
204	        .order('data_vencimento', { ascending: false });
205	
206	      const { data: contas, error: contasErr } = await contasQuery;
207	      if (contasErr) throw contasErr;
208	      const candidateContas = contas || [];
209	
210	      // 4) Get ALL reconciled conta IDs across ALL bank accounts
211	      const { data: allReconciledIds } = await supabase
212	        .from('bank_transactions')
213	        .select('conta_financeira_id')
214	        .eq('conciliado', true)
215	        .not('conta_financeira_id', 'is', null);
216	
217	      const globalUsedContaIds = new Set(
218	        (allReconciledIds || []).map((r: any) => r.conta_financeira_id)
219	      );
220	
221	      // 5) Score all candidate pairs — ULTRA-STRICT: only guaranteed matches
222	      // Requirements: exact value + strong identity (CNPJ/CPF or clear name) + close date
223	      // Anything matched here is removed from the AI pool, so zero false positives.
224	      const allCandidates: ReconciliationMatch[] = [];
225	
226	      for (const txn of bankTxns as BankTransaction[]) {
227	        const txnAmount = Math.abs(txn.valor);
228	        const txnDate = new Date(txn.data + 'T12:00:00');
229	        const isDebit = txn.tipo === 'debito';
230	
231	        // Bank fees never match algorithmically
232	        if (isBankFee(txn.descricao)) continue;
233	
234	        for (const conta of candidateContas) {
235	          if (globalUsedContaIds.has(conta.id)) continue;
236	
237	          // Type must match
238	          const typeMatch = (isDebit && conta.tipo === 'despesa') || (!isDebit && conta.tipo === 'receita');
239	          if (!typeMatch) continue;
240	
241	          // VALUE: must be exact to the cent — no tolerance
242	          const contaAmount = Math.abs(conta.valor);
243	          const valueDiff = Math.abs(txnAmount - contaAmount);
244	          if (valueDiff >= 0.01) continue;
245	
246	          // DATE: max 7 days
247	          let bestDateDiff = 999;
248	          const dates: Date[] = [];
249	          if (conta.data_vencimento) dates.push(new Date(conta.data_vencimento + 'T12:00:00'));
250	          if (conta.data_pagamento) dates.push(new Date(conta.data_pagamento + 'T12:00:00'));
251	          if (conta.data_competencia) dates.push(new Date(conta.data_competencia + 'T12:00:00'));
252	          for (const d of dates) {
253	            const diff = dateDiffDays(txnDate, d);
254	            if (diff < bestDateDiff) bestDateDiff = diff;
255	          }
256	          if (bestDateDiff > 7) continue;
257	
258	          // IDENTITY: must have CNPJ/CPF or strong description match
259	          const descResult = calcDescriptionScore(txn.descricao, conta.descricao);
260	
261	          // Only accept strong signals: CNPJ/CPF (20), description contained (18), or 2+ words (8+)
262	          // Single word match (5) is NOT enough — too risky
263	          if (descResult.score < 8) continue;
264	
265	          // Scoring
266	          const dateScore = bestDateDiff <= 0.5 ? 30 : bestDateDiff <= 1 ? 25 : bestDateDiff <= 3 ? 20 : bestDateDiff <= 5 ? 15 : 10;
267	          const originScore = conta.origem === 'nota_fiscal' ? 5 : 0;
268	          let confidence = 45 + dateScore + descResult.score + originScore;
269	          confidence = Math.min(confidence, 100);
270	
271	          // Only accept high confidence
272	          if (confidence < 80) continue;
273	
274	          const reasons: string[] = ['Valor exato'];
275	          if (bestDateDiff <= 0.5) reasons.push('Mesma data');
276	          else if (bestDateDiff <= 3) reasons.push('Data proxima');
277	          else reasons.push(`${Math.round(bestDateDiff)}d dif`);
278	          if (descResult.reason) reasons.push(descResult.reason);
279	          if (originScore > 0) reasons.push('Origem NF');
280	
281	          allCandidates.push({
282	            bankTxnId: txn.id,
283	            bankTxn: txn,
284	            contaId: conta.id,
285	            contaDescricao: conta.descricao,
286	            contaValor: conta.valor,
287	            contaVencimento: conta.data_vencimento,
288	            contaStatus: conta.status,
289	            contaTipo: conta.tipo,
290	            contaOrigem: conta.origem,
291	            confidence,
292	            matchReason: reasons.join(' | '),
293	          });
294	        }
295	      }
296	
297	      // 6) Greedy assignment: best confidence first, no reuse
298	      allCandidates.sort((a, b) => b.confidence - a.confidence);
299	
300	      const usedBankTxns = new Set<number>();
301	      const usedContas = new Set<string>();
302	      const bestMatches: ReconciliationMatch[] = [];
303	
304	      for (const m of allCandidates) {
305	        if (usedBankTxns.has(m.bankTxnId) || usedContas.has(m.contaId)) continue;
306	        usedBankTxns.add(m.bankTxnId);
307	        usedContas.add(m.contaId);
308	        bestMatches.push(m);
309	      }
310	
311	      // 7) Unmatched
312	      const unmatched: UnmatchedBankTxn[] = (bankTxns as BankTransaction[])
313	        .filter(txn => !usedBankTxns.has(txn.id))
314	        .map(txn => ({ bankTxn: txn }));
315	
316	      setBankMatches(bestMatches);
317	      setUnmatchedTxns(unmatched);
318	    } catch (e) {
319	      handleError(e, { domain: 'financeiro', operation: 'findBankMatches', showToast: false });
320	      toast.error('Erro ao buscar correspondencias');
321	    } finally {
322	      setLoading(false);
323	    }
324	  }, []);
325	
326	  const confirmBankMatch = useCallback(async (
327	    bankTxnId: number,
328	    contaId: string,
329	    accountId: number,
330	    bankTxnDate: string,
331	    contaTipo?: string,
332	  ) => {
333	    try {
334	      const { error: bankErr } = await supabase
335	        .from('bank_transactions')
336	        .update({ conciliado: true, conta_financeira_id: contaId })
337	        .eq('id', bankTxnId);
338	      if (bankErr) throw bankErr;
339	
340	      // Receitas use 'recebido' + data_recebimento, despesas use 'pago' + data_pagamento
341	      const isReceita = contaTipo === 'receita';
342	      const updateData: Record<string, any> = {
343	        status: isReceita ? 'recebido' : 'pago',
344	        ...(isReceita ? { data_recebimento: bankTxnDate } : { data_pagamento: bankTxnDate }),
345	      };
346	      const { error: contaErr } = await supabase
347	        .from('contas_pagar_receber')
348	        .update(updateData)
349	        .eq('id', contaId)
350	        .eq('status', 'pendente');
351	      if (contaErr) throw contaErr;
352	
353	      setBankMatches(prev => prev.filter(m => m.bankTxnId !== bankTxnId));
354	      toast.success('Conciliacao confirmada');
355	    } catch (e) {
356	      handleError(e, { domain: 'financeiro', operation: 'confirmBankMatch', showToast: false });
357	      toast.error('Erro ao confirmar');
358	    }
359	  }, []);
360	
361	  const confirmAllBankMatches = useCallback(async (
362	    minConfidence: number,
363	    accountId: number,
364	  ) => {
365	    const highConfidence = bankMatches.filter(m => m.confidence >= minConfidence);
366	    if (highConfidence.length === 0) return;
367	
368	    setLoading(true);
369	    let confirmed = 0;
370	    for (const m of highConfidence) {
371	      try {
372	        await supabase
373	          .from('bank_transactions')
374	          .update({ conciliado: true, conta_financeira_id: m.contaId })
375	          .eq('id', m.bankTxnId);
376	
377	        const isReceita = m.contaTipo === 'receita';
378	        const updateData: Record<string, any> = {
379	          status: isReceita ? 'recebido' : 'pago',
380	          ...(isReceita ? { data_recebimento: m.bankTxn.data } : { data_pagamento: m.bankTxn.data }),
381	        };
382	        await supabase
383	          .from('contas_pagar_receber')
384	          .update(updateData)
385	          .eq('id', m.contaId)
386	          .eq('status', 'pendente');
387	
388	        confirmed++;
389	      } catch (e) {
390	        handleError(e, { domain: 'financeiro', operation: 'confirmAllBankMatches', showToast: false });
391	      }
392	    }
393	
394	    setBankMatches(prev => prev.filter(m => m.confidence < minConfidence));
395	    toast.success(`${confirmed} transacoes conciliadas`);
396	    setLoading(false);
397	  }, [bankMatches]);
398	
399	  const dismissMatch = useCallback((bankTxnId: number) => {
400	    setBankMatches(prev => {
401	      const match = prev.find(m => m.bankTxnId === bankTxnId);
402	      if (match) {
403	        setUnmatchedTxns(u => [...u, { bankTxn: match.bankTxn }]);
404	      }
405	      return prev.filter(m => m.bankTxnId !== bankTxnId);
406	    });
407	  }, []);
408	
409	  const markConciliadoAlone = useCallback(async (bankTxn: BankTransaction, lojaId: number) => {
410	    try {
411	      const tipo = bankTxn.tipo === 'credito' ? 'receita' : 'despesa';
412	
413	      // Map bank category to DRE subaccount name
414	      const bankCat = bankTxn.categoria || 'Outros';
415	      let dreCategory = 'Identificação Pendente';
416	      const { data: mappingData } = await supabase
417	        .from('finance_category_mgmt_map')
418	        .select('mgmt_sub:finance_mgmt_subaccounts(name)')
419	        .eq('source', 'bank_ofx')
420	        .eq('source_category', bankCat)
421	        .eq('active', true)
422	        .limit(1)
423	        .single();
424	      if (mappingData) {
425	        dreCategory = (mappingData as any).mgmt_sub?.name || dreCategory;
426	      }
427	
428	      // Credit bank transactions (receita) must map to an income subaccount
429	      if (tipo === 'receita' && dreCategory === 'Identificação Pendente') {
430	        dreCategory = 'Venda Pix';
431	      }
432	
433	      // Create a conta_pagar_receber entry from the bank transaction
434	      const { data: inserted, error: insertErr } = await supabase
435	        .from('contas_pagar_receber')
436	        .insert({
437	          loja_id: lojaId,
438	          descricao: bankTxn.descricao,
439	          valor: Math.abs(bankTxn.valor),
440	          tipo,
441	          status: tipo === 'receita' ? 'recebido' : 'pago',
442	          data_vencimento: bankTxn.data,
443	          data_pagamento: tipo === 'despesa' ? bankTxn.data : null,
444	          data_recebimento: tipo === 'receita' ? bankTxn.data : null,
445	          data_competencia: bankTxn.data,
446	          categoria: dreCategory,
447	          origem: 'extrato_bancario',
448	          forma_pagamento: 'outros',
449	          numero_parcelas: 1,
450	        })
451	        .select('id')
452	        .single();
453	      if (insertErr) throw insertErr;
454	
455	      // Link bank transaction to the new conta
456	      const { error: linkErr } = await supabase
457	        .from('bank_transactions')
458	        .update({ conciliado: true, conta_financeira_id: inserted.id })
459	        .eq('id', bankTxn.id);
460	      if (linkErr) throw linkErr;
461	
462	      setBankMatches(prev => prev.filter(m => m.bankTxnId !== bankTxn.id));
463	      setUnmatchedTxns(prev => prev.filter(u => u.bankTxn.id !== bankTxn.id));
464	      toast.success('Lançamento criado e conciliado');
465	    } catch (e) {
466	      handleError(e, { domain: 'financeiro', operation: 'markConciliadoAlone', showToast: false });
467	      toast.error('Erro ao conciliar');
468	    }
469	  }, []);
470	
471	  const bulkMarkConciliadoAlone = useCallback(async (bankTxns: BankTransaction[], lojaId: number) => {
472	    let success = 0;
473	    let errors = 0;
474	    setLoading(true);
475	    for (const bankTxn of bankTxns) {
476	      try {
477	        const tipo = bankTxn.tipo === 'credito' ? 'receita' : 'despesa';
478	
479	        const bankCat = bankTxn.categoria || 'Outros';
480	        let dreCategory = 'Identificação Pendente';
481	        const { data: mappingData } = await supabase
482	          .from('finance_category_mgmt_map')
483	          .select('mgmt_sub:finance_mgmt_subaccounts(name)')
484	          .eq('source', 'bank_ofx')
485	          .eq('source_category', bankCat)
486	          .eq('active', true)
487	          .limit(1)
488	          .single();
489	        if (mappingData) {
490	          dreCategory = (mappingData as any).mgmt_sub?.name || dreCategory;
491	        }
492	
493	        if (tipo === 'receita' && dreCategory === 'Identificação Pendente') {
494	          dreCategory = 'Venda Pix';
495	        }
496	
497	        const { data: inserted, error: insertErr } = await supabase
498	          .from('contas_pagar_receber')
499	          .insert({
500	            loja_id: lojaId,
501	            descricao: bankTxn.descricao,
502	            valor: Math.abs(bankTxn.valor),
503	            tipo,
504	            status: tipo === 'receita' ? 'recebido' : 'pago',
505	            data_vencimento: bankTxn.data,
506	            data_pagamento: tipo === 'despesa' ? bankTxn.data : null,
507	            data_recebimento: tipo === 'receita' ? bankTxn.data : null,
508	            data_competencia: bankTxn.data,
509	            categoria: dreCategory,
510	            origem: 'extrato_bancario',
511	            forma_pagamento: 'outros',
512	            numero_parcelas: 1,
513	          })
514	          .select('id')
515	          .single();
516	        if (insertErr) throw insertErr;
517	
518	        const { error: linkErr } = await supabase
519	          .from('bank_transactions')
520	          .update({ conciliado: true, conta_financeira_id: inserted.id })
521	          .eq('id', bankTxn.id);
522	        if (linkErr) throw linkErr;
523	
524	        setBankMatches(prev => prev.filter(m => m.bankTxnId !== bankTxn.id));
525	        setUnmatchedTxns(prev => prev.filter(u => u.bankTxn.id !== bankTxn.id));
526	        success++;
527	      } catch (e) {
528	        errors++;
529	      }
530	    }
531	    setLoading(false);
532	    return { success, errors };
533	  }, []);
534	
535	  // ── Credit card reconciliation ──
536	
537	  const findCardMatches = useCallback(async (cardId: number) => {
538	    setLoading(true);
539	    try {
540	      const { data: allTxns, error } = await supabase
541	        .from('credit_card_transactions')
542	        .select('*')
