import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { callLLM } from './llm.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application',
}

// Types
interface BankTxn {
  id: number; data: string; descricao: string; valor: number
  tipo: 'credito' | 'debito'; categoria?: string; memo?: string
}
interface ContaRow {
  id: string; descricao: string; valor: number
  data_vencimento: string | null; data_competencia: string | null
  data_pagamento: string | null; status: string; tipo: string
  origem: string; forma_pagamento: string | null
  is_installment: boolean; parcela_numero: number | null; numero_parcelas: number
}
interface MatchResult {
  bankTxnId: number; contaId: string; confidence: number
  matchReason: string; pass: string
}

// Algorithmic Helpers
const FEE_RE = /\b(tarifa|tar\.|taxa\b|iof|anuidade|manutencao|cesta\s*de\s*servico|encargo|agrupada)/i
const NOISE = /\b(pix|ted|doc|deb|cred|auto|pag|pagamento|recebido|enviado|transf|transferencia|compra|parcela|parc|ref|nsu|aut|pgto)\b/gi
const PUNCT = /[*\-\/\\.,;:()#\[\]{}|'"!?&@=+<>_~^`]/g
const DATE_RE = /\d{2}\/\d{2}\/\d{4}/g
const CNPJ_RE = /(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/g
const CPF_RE = /(\d{3}\.?\d{3}\.?\d{3}-?\d{2})/g

function norm(d: string): string {
  return d.toLowerCase().replace(DATE_RE,' ').replace(PUNCT,' ').replace(NOISE,' ').replace(/\s+/g,' ').trim()
}
function docs(d: string): string[] {
  return [...(d.match(CNPJ_RE)||[]),...(d.match(CPF_RE)||[])].map(x=>x.replace(/[\.\-\/]/g,''))
}
function words(n: string): string[] { return n.split(/\s+/).filter(w=>w.length>3) }
function dDiff(a: string, b: string): number {
  return Math.abs((new Date(a+'T12:00:00').getTime()-new Date(b+'T12:00:00').getTime())/86400000)
}

function algoScore(txn: BankTxn, c: ContaRow): {confidence:number;reason:string}|null {
  if ((txn.tipo==='debito')!==(c.tipo==='despesa')) return null
  const tA=Math.abs(txn.valor), cA=Math.abs(c.valor)
  const vD=Math.abs(tA-cA)
  if (vD>=0.01) return null
  let bestD=999
  for (const d of [c.data_vencimento,c.data_pagamento,c.data_competencia])
    if(d){const diff=dDiff(txn.data,d);if(diff<bestD)bestD=diff}
  if(bestD>7)return null
  const bD=docs(txn.descricao),cD=docs(c.descricao)
  let identityScore=0, identityReason=''
  if(bD.length>0&&cD.length>0&&bD.some(b=>cD.includes(b))){
    identityScore=25;identityReason='CNPJ/CPF identico'
  } else {
    const bn=norm(txn.descricao),cn=norm(c.descricao)
    if(bn.length>6&&cn.length>6&&(bn.includes(cn)||cn.includes(bn))){
      identityScore=20;identityReason='Descricao contida'
    } else {
      const bw=words(bn),cw=words(cn)
      const matched=cw.filter(w=>bw.some(b=>b.includes(w)||w.includes(b)))
      if(matched.length>=2){
        identityScore=15;identityReason=`Palavras: ${matched.slice(0,3).join(', ')}`
      }
    }
  }
  if(identityScore===0) return null
  if(FEE_RE.test(txn.descricao)) return null
  const dSc=bestD<=0.5?30:bestD<=1?25:bestD<=3?20:bestD<=5?15:10
  const conf=Math.min(100, 45 + dSc + identityScore + (c.origem==='nota_fiscal'?5:0))
  if(conf<80) return null
  const r:string[]=['Valor exato']
  if(bestD<=0.5)r.push('Mesma data');else if(bestD<=3)r.push('Data proxima');else r.push(`${Math.round(bestD)}d dif`)
  r.push(identityReason)
  if(c.origem==='nota_fiscal')r.push('NF')
  return{confidence:conf,reason:r.join(' | ')}
}

function algoPass(txns: BankTxn[], contas: ContaRow[], used: Set<string>): {matches:MatchResult[];unmatched:BankTxn[]} {
  const cands:{bankId:number;contaId:string;conf:number;reason:string}[]=[] 
  for(const t of txns)for(const c of contas){
    if(used.has(c.id))continue
    const r=algoScore(t,c)
    if(r)cands.push({bankId:t.id,contaId:c.id,conf:r.confidence,reason:r.reason})
  }
  cands.sort((a,b)=>b.conf-a.conf)
  const uB=new Set<number>(),uC=new Set<string>()
  const matches:MatchResult[]=[]
  for(const c of cands){
    if(uB.has(c.bankId)||uC.has(c.contaId))continue
    uB.add(c.bankId);uC.add(c.contaId)
    matches.push({bankTxnId:c.bankId,contaId:c.contaId,confidence:c.conf,matchReason:c.reason,pass:'algorithmic'})
  }
  return{matches,unmatched:txns.filter(t=>!uB.has(t.id))}
}

function batch<T>(arr:T[],sz:number):T[][]{const b:T[][]=[];for(let i=0;i<arr.length;i+=sz)b.push(arr.slice(i,i+sz));return b}

function preFilt(txn:BankTxn,contas:ContaRow[],used:Set<string>,wideValue=false):ContaRow[]{
  const target=txn.tipo==='debito'?'despesa':'receita'
  const tA=Math.abs(txn.valor)
  const valTol=wideValue?0.02:0.01
  const dateTol=wideValue?15:10
  const candidates:{conta:ContaRow;bestDate:number}[]=[] 
  for(const c of contas){
    if(used.has(c.id)||c.tipo!==target)continue
    const cA=Math.abs(c.valor)
    if(cA===0)continue
    if(Math.abs(tA-cA)>cA*valTol)continue
    let bestD=999
    for(const d of[c.data_vencimento,c.data_pagamento,c.data_competencia])
      if(d){const diff=dDiff(txn.data,d);if(diff<bestD)bestD=diff}
    if(bestD>dateTol)continue
    candidates.push({conta:c,bestDate:bestD})
  }
  candidates.sort((a,b)=>a.bestDate-b.bestDate)
  return candidates.slice(0,12).map(x=>x.conta)
}

const SYS_PROMPT=`# ROLE
Voce e um contador forense senior especializado em conciliacao bancaria de empresas brasileiras do setor alimenticio (padarias, confeitarias, restaurantes). Voce possui 20 anos de experiencia com extratos OFX, contas a pagar/receber, e sistemas ERP.

# CONTEXTO
A empresa opera multiplas lojas fisicas. Receitas vem de maquininhas (Stone, Cielo, Rede, GetNet, PagSeguro, Safrapay), delivery (iFood, Rappi, Uber Eats), e PIX. Despesas incluem fornecedores de insumos, folha de pagamento, aluguel, contas de consumo (energia, agua, internet), impostos, e taxas bancarias.

Voce recebera transacoes do extrato bancario (B) e contas a pagar/receber do sistema (C). Sua tarefa e identificar quais transacoes bancarias correspondem a quais contas.

# FRAMEWORK DE ANALISE

## Passo 1: IDENTIDADE
Extraia o nome da pessoa/empresa de AMBOS os lados e verifique se sao o mesmo ente.

## Passo 2: DIRECAO
- DEBITO bancario = DESPESA no sistema
- CREDITO bancario = RECEITA no sistema

## Passo 3: VALOR — DEVEM ser identicos
- Valor DEVE ser identico (diferenca maxima de R$0.50 por arredondamento)
- Qualquer diferenca > 1% = REJEITAR imediatamente, sem excecoes
- NAO aceite valores "proximos" ou "parecidos" — somente exatos

## Passo 4: DATA
- Mesmo dia ou +/- 1 dia: forte evidencia
- 2-7 dias: normal para boletos e processamento bancario
- 8-15 dias: aceitavel para maquininhas
- > 15 dias: somente com identidade muito forte

## Passo 5: CONTEXTO SEMANTICO
- "TARIFA PIX" = taxa DO BANCO, nao pagamento PIX a fornecedor
- "Recebimento vendas Stone" = receita de maquininha
- "FOLHA PAGAMENTO" = salarios

# PARCELAS (PRESTACOES)
Algumas contas sao parceladas (ex: salario em 11x, fornecedor em 3x). Cada parcela aparece com "[Parcela X/Y]".
- SEMPRE concilie com a parcela do MES CORRETO baseado na data_vencimento
- Se ha varias parcelas da mesma pessoa, escolha aquela cuja data_vencimento esta mais proxima da data do extrato
- NUNCA concilie um valor mensal do extrato com o valor TOTAL da conta parcelada

# ARMADILHAS
1. Dois debitos de R$500 no mesmo dia NAO sao necessariamente a mesma transacao
2. "TARIFA PIX" NAO e o mesmo que "Pagamento via PIX" a fornecedor
3. Valores redondos iguais sem identidade = coincidencia, NAO match
4. "DAS" (imposto Simples) NAO e "venDAS"
5. Transferencia entre contas proprias NAO deve ser conciliada
6. Valor diferente = NAO e match, mesmo que o nome bata
7. Parcela do mes errado = NAO e match

# REGRAS ABSOLUTAS
1. Cada B casa com NO MAXIMO 1 C. Cada C com NO MAXIMO 1 B.
2. Falso positivo e PIOR que miss. Na duvida, NAO faca match.
3. VALOR DEVE SER IDENTICO (tolerancia maxima R$0.50). Diferenca > 1% = REJEITAR.
4. confidence: 60-95. Use 85+ somente com identidade forte + valor IDENTICO + data coerente.
5. Para parcelas [Parcela X/Y], escolha a parcela com data_vencimento mais proxima da data do extrato.
6. Se nao ha NENHUM match confiante, retorne {"matches":[]}.

# OUTPUT — retorne APENAS este JSON, sem texto adicional:
{"matches":[{"bank_id":"B1","conta_id":"C3","confidence":85,"reason":"Stone vendas cartao debito, valor identico, D+2 do vencimento"}]}`

const SYS_PROMPT_DETAILED=`# ROLE
Voce e o analista SENIOR de conciliacao bancaria — ultima linha de defesa. As transacoes abaixo ja passaram por algoritmo exato e IA batch.

# CONTEXTO
Empresa brasileira do setor alimenticio com multiplas lojas.

# RAZOES PARA NAO TER SIDO CONCILIADO ANTES
1. Descricoes truncadas pelo banco
2. Valores com pequena diferenca
3. Datas distantes por atraso
4. Nome fantasia diferente da razao social
5. Pagamento parcelado — concilie SOMENTE com a parcela do mes correto
6. Banco truncou o nome do beneficiario

# ANALISE AVANCADA

## 1. DECOMPOSICAO SEMANTICA
- "PIX J FERR DIST" = "Jose Ferreira Distribuidora"
- "TED 341 CARLOS M" = "Carlos Mendes" via Itau

## 2. PADROES DE NEGOCIO
- Padaria: distribuidora, moinho, laticinio = fornecedores
- Valor DEVE ser identico para fazer match

## 3. VALORES DEVEM SER EXATOS
- Diferenca maxima R$0.50
- Diferenca > 1% = REJEITAR, sem excecoes
- NAO invente justificativas para aceitar valores diferentes

# REGRAS
1. Cada B casa com no maximo 1 C.
2. VALOR DEVE SER IDENTICO. Diferenca > 1% = REJEITAR.
3. confidence: 60-90.
4. Qualidade > Quantidade.
5. Para parcelas [Parcela X/Y], escolha a parcela com data_vencimento mais proxima.
6. Se nao ha match confiante, retorne {"matches":[]}.

# OUTPUT — retorne APENAS JSON:
{"matches":[{"bank_id":"B1","conta_id":"C3","confidence":75,"reason":"Nome parcial corresponde, valor identico, data D+5"}]}`

async function llmPass(
  txns:BankTxn[], contas:ContaRow[], used:Set<string>,
  passName:string, model:string, detailed:boolean
):Promise<{matches:MatchResult[];still:BankTxn[]}> {
  if(txns.length===0)return{matches:[],still:[]}

  type TxnBatch={txn:BankTxn;candidates:ContaRow[];candidateMap:Map<string,string>}
  const items:TxnBatch[]=[] 
  for(const txn of txns){
    const cands=preFilt(txn,contas,used,detailed)
    if(cands.length>0){
      const cMap=new Map<string,string>()
      cands.forEach((c,i)=>cMap.set(`C${i+1}`,c.id))
      items.push({txn,candidates:cands,candidateMap:cMap})
    }
  }
  if(items.length===0)return{matches:[],still:txns}

  const BSIZ=detailed?10:20
  const batches=batch(items,BSIZ)
  const allMatches:MatchResult[]=[]
  const matchedBank=new Set<number>()

  const MAX_CONC=5
  for(let i=0;i<batches.length;i+=MAX_CONC){
    const chunk=batches.slice(i,i+MAX_CONC)
    const results=await Promise.all(chunk.map(async(bt,bi)=>{
      const bLines=bt.map(({txn},j)=>
        `B${j+1}: ${txn.data} | ${txn.tipo.toUpperCase()} | R$${Math.abs(txn.valor).toFixed(2)} | "${txn.descricao}"${txn.categoria?` [${txn.categoria}]`:''}`
      ).join('\n')

      const seenC=new Map<string,{conta:ContaRow;ref:string}>()
      let cIdx=1
      for(const item of bt){
        for(const c of item.candidates){
          if(!seenC.has(c.id)&&!used.has(c.id)){
            const ref=`C${cIdx++}`
            seenC.set(c.id,{conta:c,ref})
          }
        }
      }
      const refToId=new Map<string,string>()
      const cLines:string[]=[] 
      for(const[id,{conta,ref}]of seenC){
        refToId.set(ref,id)
        const dt=conta.data_vencimento||conta.data_competencia||'sem data'
        const parcelaTag=conta.is_installment?` [Parcela ${conta.parcela_numero}/${conta.numero_parcelas}]`:''
        cLines.push(`${ref}: ${dt} | ${conta.tipo} | R$${Math.abs(conta.valor).toFixed(2)} | ${conta.status} | "${conta.descricao}"${parcelaTag}${conta.origem==='nota_fiscal'?' [NF]':''}`)
      }

      const bankRefMap=new Map<string,number>()
      bt.forEach(({txn},j)=>bankRefMap.set(`B${j+1}`,txn.id))

      const userMsg=`TRANSACOES BANCARIAS:\n${bLines}\n\nCONTAS CANDIDATAS:\n${cLines.join('\n')}\n\nRetorne matches usando os IDs B1,B2... e C1,C2... mostrados.`

      try{
        const r=await callLLM(
          [{role:'system',content:detailed?SYS_PROMPT_DETAILED:SYS_PROMPT},{role:'user',content:userMsg}],
          model,30000
        )
        const txt=String(r.content||'').replace(/```json/g,'').replace(/```/g,'')
        const jsonMatch=txt.match(/\{[\s\S]*\}/)
        if(!jsonMatch)return{matches:[],refToId,bankRefMap}
        const parsed=JSON.parse(jsonMatch[0])
        return{matches:Array.isArray(parsed.matches)?parsed.matches:[],refToId,bankRefMap}
      }catch(e){
        console.error(`[${passName}] Batch ${i+bi} failed:`,e)
        return{matches:[],refToId,bankRefMap}
      }
    }))

    const txnMap=new Map(txns.map(t=>[t.id,t]))
    const contaMap=new Map(contas.map(c=>[c.id,c]))

    for(const res of results){
      if(!res||!('matches' in res))continue
      for(const m of res.matches){
        const bankRef=String(m.bank_id||'')
        const contaRef=String(m.conta_id||'')
        const conf=Number(m.confidence)||0
        const bankId=res.bankRefMap.get(bankRef)
        const contaId=res.refToId.get(contaRef)
        if(!bankId||!contaId||conf<60)continue
        if(matchedBank.has(bankId)||used.has(contaId))continue

        // POST-VALIDATION: reject LLM matches where values don't match (max 1% tolerance)
        const txnObj=txnMap.get(bankId)
        const contaObj=contaId?contaMap.get(contaId):null
        if(txnObj&&contaObj){
          const tA=Math.abs(txnObj.valor),cA=Math.abs(contaObj.valor)
          if(cA>0&&Math.abs(tA-cA)/cA>0.01){
            console.log(`[${passName}] REJECTED: bank ${bankId} R$${tA.toFixed(2)} vs conta ${contaId} R$${cA.toFixed(2)} — value mismatch ${((Math.abs(tA-cA)/cA)*100).toFixed(1)}%`)
            continue
          }
        }

        matchedBank.add(bankId)
        used.add(contaId)
        allMatches.push({
          bankTxnId:bankId,contaId,
          confidence:Math.min(95,conf),
          matchReason:`\u{1F916} ${String(m.reason||'Match por IA')}`,
          pass:passName
        })
      }
    }
  }

  return{matches:allMatches,still:txns.filter(t=>!matchedBank.has(t.id))}
}

serve(async(req:Request)=>{
  if(req.method==='OPTIONS')return new Response('ok',{headers:corsHeaders})
  try{
    const{account_id}=await req.json()
    if(!account_id)throw new Error('Missing account_id')

    const sb=createClient(Deno.env.get('SUPABASE_URL')??'',Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')??'')

    console.log(`[AI Recon] Start account=${account_id}`)

    const{data:acct}=await sb.from('bank_accounts').select('loja_id').eq('id',account_id).single()
    if(!acct)throw new Error('Account not found')

    const{data:rawTxns}=await sb.from('bank_transactions')
      .select('id,data,descricao,valor,tipo,categoria,memo')
      .eq('bank_account_id',account_id).eq('conciliado',false)
      .order('data',{ascending:false})

    const txns=(rawTxns||[])as BankTxn[]
    if(txns.length===0){
      return new Response(JSON.stringify({matches:[],unmatched:[],stats:{total:0,pass1:0,pass2:0,pass3:0,unmatched:0}}),
        {headers:{...corsHeaders,'Content-Type':'application/json'}})
    }

    // Include pendente + pago/recebido: some entries may be manually marked pago but not yet linked to a bank txn.
    // The 'used' set (already-linked conta IDs) prevents double-matching.
    const{data:rawContas}=await sb.from('financial_transactions_unified')
      .select('id,descricao,valor,data_vencimento,data_competencia,data_pagamento,status,tipo,origem,forma_pagamento,is_installment,parcela_numero,numero_parcelas')
      .eq('loja_id',acct.loja_id)
      .eq('is_parent',false)
      .in('status',['pendente','pago','recebido'])
      .or('forma_pagamento.is.null,forma_pagamento.neq.cartao_credito')
    const contas=(rawContas||[])as ContaRow[]

    const{data:usedRaw}=await sb.from('bank_transactions')
      .select('conta_financeira_id').eq('conciliado',true).not('conta_financeira_id','is',null)
    const used=new Set<string>((usedRaw||[]).map((r:any)=>r.conta_financeira_id))

    console.log(`[AI Recon] ${txns.length} txns, ${contas.length} contas`)

    console.log('[Pass 1] Algorithmic...')
    const p1=algoPass(txns,contas,used)
    for(const m of p1.matches)used.add(m.contaId)
    console.log(`[Pass 1] ${p1.matches.length} matches, ${p1.unmatched.length} remain`)

    let p2={matches:[] as MatchResult[],still:p1.unmatched}
    if(p1.unmatched.length>0){
      console.log('[Pass 2] LLM batch...')
      p2=await llmPass(p1.unmatched,contas,used,'ai_batch','google/gemini-2.0-flash-001',false)
      console.log(`[Pass 2] ${p2.matches.length} matches, ${p2.still.length} remain`)
    }

    let p3={matches:[] as MatchResult[],still:p2.still}
    if(p2.still.length>0&&p2.still.length<=80){
      console.log('[Pass 3] LLM detailed...')
      p3=await llmPass(p2.still,contas,used,'ai_detailed','google/gemini-2.0-flash-001',true)
      console.log(`[Pass 3] ${p3.matches.length} matches`)
    }

    const all=[...p1.matches,...p2.matches,...p3.matches]
    const mIds=new Set(all.map(m=>m.bankTxnId))
    const cMap=new Map(contas.map(c=>[c.id,c]))
    const tMap=new Map(txns.map(t=>[t.id,t]))

    const enriched=all.map(m=>{
      const c=cMap.get(m.contaId)
      return{
        bankTxnId:m.bankTxnId,
        bankTxn:tMap.get(m.bankTxnId),
        contaId:m.contaId,
        contaDescricao:c?.descricao||'',
        contaValor:c?.valor||0,
        contaVencimento:c?.data_vencimento||null,
        contaStatus:c?.status||'',
        contaTipo:c?.tipo||'',
        contaOrigem:c?.origem||'',
        confidence:m.confidence,
        matchReason:m.matchReason,
        pass:m.pass,
        contaIsInstallment:!!c?.is_installment,
        contaParcelaInfo:c?.is_installment?`${c.parcela_numero}/${c.numero_parcelas}`:undefined,
      }
    })

    const stats={total:txns.length,pass1:p1.matches.length,pass2:p2.matches.length,pass3:p3.matches.length,
      total_matches:all.length,unmatched:txns.filter(t=>!mIds.has(t.id)).length}

    console.log('[AI Recon] Done',JSON.stringify(stats))

    return new Response(JSON.stringify({
      matches:enriched,
      unmatched:txns.filter(t=>!mIds.has(t.id)).map(t=>({bankTxn:t})),
      stats,
    }),{headers:{...corsHeaders,'Content-Type':'application/json'}})

  }catch(e:any){
    console.error('[AI Recon] Error:',e.message)
    return new Response(JSON.stringify({error:e.message}),
      {headers:{...corsHeaders,'Content-Type':'application/json'},status:400})
  }
})
